/* 基本 Flexbox 佈局 */
.container {
  display: flex;
  flex-direction: row;
  gap: 16px;              /* 項目間距 */
}

.item {
  flex: 1;                /* 等分剩餘空間 */
  padding: 16px;
  background: #f0f0f0;
  box-sizing: border-box;
}

/* Media Query：小螢幕改為垂直排列 */
@media (max-width: 600px) {
  .container {
    flex-direction: column;
  }
}

